  if (/[\u0000- \u007f-\u009f"<>\\`\u200b-\u200f\u2028\u2029\u202a-\u202e\u2066-\u2069\ufeff]/.test(u)) return '';
  const m = u.match(/^https?:\/\/([^/?#]*)(?:[/?#]|$)/i);
  if (!m || !/^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?::\d{1,5})?$/i.test(m[1])) return '';
